ALTER TABLE media_assets ADD COLUMN IF NOT EXISTS original_name TEXT;
ALTER TABLE media_assets ADD COLUMN IF NOT EXISTS analysis_status TEXT NOT NULL DEFAULT 'not_requested';
ALTER TABLE media_assets ADD COLUMN IF NOT EXISTS analysis_metadata JSONB NOT NULL DEFAULT '{}';
CREATE TABLE IF NOT EXISTS asset_analysis_jobs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),asset_id UUID NOT NULL REFERENCES media_assets(id) ON DELETE CASCADE,project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,requested_kinds JSONB NOT NULL DEFAULT '[]',status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','processing','completed','partial','failed','unavailable')),attempt INTEGER NOT NULL DEFAULT 0,max_attempts INTEGER NOT NULL DEFAULT 3,available_at TIMESTAMPTZ NOT NULL DEFAULT now(),lease_owner TEXT,lease_expires_at TIMESTAMPTZ,error TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS asset_analysis_claim_idx ON asset_analysis_jobs(status,available_at,created_at);
CREATE INDEX IF NOT EXISTS asset_analysis_asset_idx ON asset_analysis_jobs(asset_id,created_at DESC);
CREATE TABLE IF NOT EXISTS asset_extractions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),asset_id UUID NOT NULL REFERENCES media_assets(id) ON DELETE CASCADE,job_id UUID REFERENCES asset_analysis_jobs(id) ON DELETE CASCADE,kind TEXT NOT NULL,status TEXT NOT NULL,content TEXT,structured JSONB NOT NULL DEFAULT '{}',tool_name TEXT,confidence REAL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS asset_extractions_asset_kind_idx ON asset_extractions(asset_id,kind,created_at DESC);
CREATE TABLE IF NOT EXISTS media_chunks(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),asset_id UUID NOT NULL REFERENCES media_assets(id) ON DELETE CASCADE,project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,kind TEXT NOT NULL,content TEXT NOT NULL,ordinal INTEGER NOT NULL DEFAULT 0,page INTEGER,start_seconds REAL,end_seconds REAL,metadata JSONB NOT NULL DEFAULT '{}',search_vector tsvector GENERATED ALWAYS AS (to_tsvector('simple',coalesce(content,''))) STORED,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS media_chunks_project_idx ON media_chunks(project_id,asset_id);
CREATE INDEX IF NOT EXISTS media_chunks_fts_idx ON media_chunks USING GIN(search_vector);
CREATE TABLE IF NOT EXISTS media_keyframes(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),asset_id UUID NOT NULL REFERENCES media_assets(id) ON DELETE CASCADE,project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,timestamp_seconds REAL NOT NULL,storage_key TEXT NOT NULL,description TEXT,metadata JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(asset_id,timestamp_seconds));
CREATE INDEX IF NOT EXISTS media_keyframes_asset_idx ON media_keyframes(asset_id,timestamp_seconds);
